'use client';

// The tick-box half of the pre-service handover checklist.
//
// State is intentionally local: the list is a one-sitting aid, and persisting it
// would need an API field (out of scope for this change). The page says so, and
// the progress card says it again where the ticks actually are.
//
// The checklist itself is generated by `lib/handover-checklist.ts` from the
// device's category, serial, purchase place and warranty end. Item IDs are
// stable across languages, so switching VI/EN keeps ticks in place.

import * as React from 'react';
import {
  AlertTriangle,
  Camera,
  ClipboardCheck,
  FileText,
  KeyRound,
  PackageCheck,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { useLocale, useT } from '@/lib/i18n/client';
import {
  buildHandoverChecklist,
  handoverPrepKind,
  type HandoverChecklistInput,
  type HandoverGroupId,
} from '@/lib/handover-checklist';
import { cn } from '@/lib/utils';

const GROUP_ICONS: Record<
  HandoverGroupId,
  React.ComponentType<{ className?: string }>
> = {
  data: KeyRound,
  condition: Camera,
  paperwork: FileText,
  counter: ClipboardCheck,
  pickup: PackageCheck,
};

export function HandoverChecklist({
  device,
}: {
  device: HandoverChecklistInput & { name: string };
}) {
  const t = useT();
  const locale = useLocale();
  const checklist = React.useMemo(
    () => buildHandoverChecklist(device, locale),
    [device, locale],
  );
  const [checked, setChecked] = React.useState<Set<string>>(() => new Set());
  const prepKind = handoverPrepKind(device.category);

  const done = checklist.groups.reduce(
    (sum, group) =>
      sum + group.items.filter((item) => checked.has(item.id)).length,
    0,
  );

  const toggle = (id: string) => {
    setChecked((previous) => {
      const next = new Set(previous);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  return (
    <div className="space-y-6">
      <div className="rounded-lg border-[1.5px] border-amber-200 bg-amber-soft px-4 py-3 text-sm text-amber-ink">
        <p className="flex items-start gap-2">
          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
          <span>
            {prepKind === 'phone'
              ? t(
                  'Máy còn passcode hoặc tài khoản iCloud/Google/Mi có thể bị từ chối ngay ở quầy. Cửa hàng cũng có thể xoá dữ liệu khi tiếp nhận — hãy sao lưu trước.',
                )
              : prepKind === 'computer'
                ? t(
                    'Máy còn mật khẩu hoặc tài khoản iCloud/Microsoft/Google có thể bị từ chối ngay ở quầy. Cửa hàng cũng có thể xoá dữ liệu khi tiếp nhận — hãy sao lưu trước.',
                  )
                : t(
                    'Cửa hàng có thể kiểm tra tem máy và giấy tờ trước khi nhận. Chụp lại tình trạng máy và giữ phiếu tiếp nhận.',
                  )}
          </span>
        </p>
      </div>

      <Card tone="muted">
        <CardContent className="space-y-3 p-card">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <p className="text-sm font-semibold text-ink" aria-live="polite">
              {t('Đã xong {done}/{total} mục', {
                done,
                total: checklist.total,
              })}
            </p>
            {done > 0 && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="rounded-pill"
                onClick={() => setChecked(new Set())}
              >
                {t('Bỏ đánh dấu')}
              </Button>
            )}
          </div>
          <Progress
            value={checklist.total === 0 ? 0 : (done / checklist.total) * 100}
            aria-label={t('Đã xong {done}/{total} mục', {
              done,
              total: checklist.total,
            })}
          />
          <p className="text-xs leading-relaxed text-muted-foreground">
            {t(
              'Danh sách chỉ để bạn tự kiểm tra — app không lưu trạng thái đánh dấu. Đóng hoặc tải lại trang là mất.',
            )}
          </p>
        </CardContent>
      </Card>

      {checklist.groups.map((group) => {
        const Icon = GROUP_ICONS[group.id];
        const groupDone = group.items.filter((item) => checked.has(item.id)).length;
        return (
          <Card key={group.id}>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Icon className="h-5 w-5 text-primary" />
                {group.title}
                <span className="ml-auto text-xs font-medium text-muted-foreground">
                  {groupDone}/{group.items.length}
                </span>
              </CardTitle>
            </CardHeader>
            <CardContent className="divide-y divide-border pt-0">
              {group.items.map((item) => {
                const isDone = checked.has(item.id);
                return (
                  <label
                    key={item.id}
                    htmlFor={`handover-${item.id}`}
                    className="flex cursor-pointer items-start gap-3 py-3"
                  >
                    <input
                      id={`handover-${item.id}`}
                      type="checkbox"
                      checked={isDone}
                      onChange={() => toggle(item.id)}
                      className="mt-1 h-4 w-4 shrink-0 accent-primary"
                    />
                    <span className="min-w-0 flex-1">
                      <span
                        className={cn(
                          'block text-sm font-semibold leading-relaxed text-ink',
                          isDone && 'text-muted-foreground line-through',
                        )}
                      >
                        {item.title}
                      </span>
                      {item.detail && (
                        <span className="mt-0.5 block text-xs leading-relaxed text-muted-foreground">
                          {item.detail}
                        </span>
                      )}
                    </span>
                  </label>
                );
              })}
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}
